def w3(n):
    s = ''
    h = n // 100
    t = (n % 100) // 10
    u = n % 10
    if h:
        s += ('' if h == 1 else ONES[h] + ' ') + 'yüz '
    if t:
        s += TENS[t] + ' '
    if u:
        s += ONES[u] + ' '
    return s.strip()
def words(n):
    if n == 0:
        return 'sıfır'
    p = []
    m = n // 1000000
    k = (n % 1000000) // 1000
    r = n % 1000
    if m:
        p.append(w3(m) + ' milyon')
    if k:
        p.append(('' if k == 1 else w3(k) + ' ') + 'bin')
    if r:
        p.append(w3(r))
    return ' '.join(p)
def amt(x, key):
    c = int(round(abs(float(x or 0)) * 100))
    a = c // 100
    b = c % 100
    if key == 'debtTL':
        if b:
            return (words(a) + ' lira ' if a else '') + words(b) + ' kuruş'
        return words(a) + ' Türk Lirası'
    mj, mn = UNITS[key]
    s = words(a) + ' ' + mj
    if b:
        s += ' ' + words(b) + ' ' + mn
    return s
def dsay(s):
    m = re.match(r'([0-9]{2})[.]([0-9]{2})[.]([0-9]{4})', str(s or ''))
    if not m:
        return ''
    return str(int(m.group(1))) + ' ' + MON[int(m.group(2)) - 1] + ' ' + m.group(3)
def dkey(s):
